const fs = require("fs");
const path = require("path");

// The canonical FileExportPlugin is generated by configure-android-share.js.
// This step deliberately validates that implementation instead of overwriting it.
const config = JSON.parse(fs.readFileSync(path.join(__dirname, "capacitor.config.json"), "utf8"));
const packagePath = config.appId.split(".").join(path.sep);
const pluginPath = path.join(__dirname, "android", "app", "src", "main", "java", packagePath, "FileExportPlugin.java");
if (!fs.existsSync(pluginPath)) {
  throw new Error("FileExportPlugin.java is missing. Run configure-android-share.js first.");
}
const source = fs.readFileSync(pluginPath, "utf8");
const required = [
  "saveHtmlAsImages",
  "printHtml",
  "writeWebViewToPdf",
  "android.graphics.pdf.PdfDocument",
  "PdfRenderer",
  "removePartialImages.run()"
];
const missing = required.filter(marker => !source.includes(marker));
if (missing.length) {
  throw new Error("The canonical Android PDF/image exporter is incomplete: " + missing.join(", "));
}
if (source.includes("adapter.onLayout(") || source.includes("adapter.onWrite(")) {
  throw new Error("Unsupported direct PrintDocumentAdapter callbacks were detected.");
}
console.log("Verified the canonical Android native print/PDF/image exporter; no files were overwritten.");
